    output logic [511:0] dma_output_tdata,
    output logic dma_output_tlast,
    output logic dma_output_tvalid,
    input logic dma_output_tready,

    // One parser-error status beat per frame with its own handshake and TLAST.
    output logic [31:0] frame_status_tdata,
    output logic frame_status_tlast,
    output logic frame_status_tvalid,
    input logic frame_status_tready
);

